          const art = getUnitArt(imported?.unitId ?? null);
          portrait.src = art?.sprite?.src ?? './dist/assets/units/default/default.svg';
          portrait.alt = imported?.unitName ?? `Avatar ${avatarId}`;
          portraitFrame.appendChild(portrait);
